export type FeeCategory={id:number;name:string;code:string;description?:string|null;display_order:number;status:'ACTIVE'|'INACTIVE';owner_scope?:'UNIVERSITY'|'COLLEGE';college_id?:number|null};
export type FeeHead={id:number;fee_category_id:number;name:string;code:string;category:FeeCategory;description?:string|null;is_refundable:boolean;status:'ACTIVE'|'INACTIVE';owner_scope?:'UNIVERSITY'|'COLLEGE';college_id?:number|null};
export type FeePeriodSetting={period_no:number;due_date?:string|null;is_mandatory:boolean;is_enrollment_clearance_required:boolean;installment_allowed:boolean;display_order:number;status:'ACTIVE'|'INACTIVE'};
export type FeeItem={id:number;fee_head_id:number;amount:string;due_date?:string|null;period_amounts?:{period_no:number;amount:string}[];period_exclusions?:{period_no:number}[];period_settings?:FeePeriodSetting[];is_mandatory:boolean;is_enrollment_clearance_required:boolean;installment_allowed:boolean;display_order:number;status:'ACTIVE'|'INACTIVE';head:FeeHead};
export type FeeStructure={id:number;academic_period_bounds?:{period_no:number;name:string;start_date:string;end_date:string;curriculum_effective_from?:string|null;curriculum_effective_to?:string|null}[];name:string;code:string;purpose:string;charge_basis:'ONE_TIME'|'PER_TERM'|'PER_ACADEMIC_YEAR'|'SPECIFIC_TERM'|'SPECIFIC_ACADEMIC_YEAR';charge_period_no?:number|null;college_applicability?:'MANDATORY'|'OPTIONAL'|null;currency:string;status:'ACTIVE'|'INACTIVE';notes?:string|null;adoption_status?:'ADOPTED'|'NOT_ADOPTED'|null;effective_for_college?:boolean;academic_session?:{id:number;name:string;code:string;status:string};program_template?:{id:number;name:string;code:string;term_structure?:string;duration_terms?:number}|null;curriculum?:{id:number;name:string;code:string;version?:string;terms?:{sequence_no:number;name:string;status:string}[]}|null;offering?:{id:number;program_template:{id:number;name:string;code:string;term_structure?:string;duration_terms?:number};academic_session:{id:number;name:string;code:string;status:string};curriculum?:{terms?:{sequence_no:number;name:string;status:string}[]}|null}|null;items:FeeItem[]};
export type Can={categoryCreate:boolean;categoryUpdate:boolean;categoryEnable:boolean;categoryDisable:boolean;headCreate:boolean;headUpdate:boolean;headEnable:boolean;headDisable:boolean;structureCreate:boolean;structureUpdate:boolean;structureEnable:boolean;structureDisable:boolean;structureAdopt:boolean};
